def sum_numbers():
    """Reads whole numbers from standard input, one per line, and prints their sum."""
    total_sum = 0
    while True:
        try:
            line = input()
            if not line:
                break
            number = int(line.strip())
            total_sum += number
        except ValueError:
            # If the input is not a valid integer, we skip it or handle as needed.
            # For this problem, we assume valid integer input as per the prompt,
            # but robust code handles errors. We'll just skip non-integers.
            continue
    print(total_sum)

if __name__ == "__main__":
    sum_numbers()
